import { connectionSummary } from "./discoveryEvidence";
import type { LiveDoor } from "./agentApi";
import "./connection-evidence.css";

type Evidence = Pick<LiveDoor, "title" | "category"> & Partial<LiveDoor>;

// Explainability is supplied by Qloo, not generated by the browser. Bound its
// presentation and omit credential-like fields even for historical saved doors.
export function safeConnectionMetadata(value: unknown, depth = 0): unknown {
  if (depth > 5) return "[Further detail omitted]";
  if (Array.isArray(value)) return value.slice(0, 20).map(item => safeConnectionMetadata(item, depth + 1));
  if (value && typeof value === "object") return Object.fromEntries(
    Object.entries(value).filter(([key]) => !/(secret|key|token|authorization|password|credential|prompt|reasoning|thought)/i.test(key))
      .slice(0, 30).map(([key, item]) => [key, safeConnectionMetadata(item, depth + 1)]));
  return typeof value === "string" ? value.slice(0, 1500) : value;
}

export default function ConnectionEvidence({ door, mode, anchors = [] }: {
  door: Evidence; mode: "demo" | "live"; anchors?: string[];
}) {
  const live = mode === "live" && !!door.entityId;
  return <details className="connection-evidence">
    <summary>Why this connection?</summary>
    <div className="connection-evidence-content">
      <span className="eyebrow">{live ? "Qloo-grounded information" : mode === "demo" ? "Authored example · not Qloo data" : "Limited historical evidence"}</span>
      <dl>
        <div><dt>Starting interest</dt><dd>{door.source || anchors.join(", ") || "Not recorded"}</dd></div>
        <div><dt>Connecting discovery</dt><dd>{door.title} · {door.category}</dd></div>
      </dl>
      <p>{connectionSummary(door, mode)}</p>
      <span className="eyebrow">Open Door interpretation · rule-based, not AI-generated</span>
      <p>{live ? door.discoveryDistance?.rationale || "A cultural direction to preview and discuss. Retrieval does not guarantee that it suits you." : "An illustrative starting point to adapt, not evidence of a cultural relationship."}</p>
      {live && <details><summary>Returned source details</summary>
        <p>Qloo entity: {door.entityId} · {door.entityType || "type not recorded"}</p>
        {door.popularity != null && <p>Returned popularity: {door.popularity} — not affinity or a personal match score.</p>}
        {door.explainability != null ? <><p>Qloo explainability, as returned (bounded excerpt). Values are not relabeled as personal affinity.</p>
          <pre>{JSON.stringify(safeConnectionMetadata(door.explainability), null, 2)}</pre></> :
          <p>No detailed relationship or affinity metadata was returned with this result.</p>}
      </details>}
    </div>
  </details>;
}
